<script setup lang="ts">import type{MovementSummary}from'../types';import{directionLabel}from'../utils/labels';import{showMonthDayTime,showTime}from'../utils/time';withDefaults(defineProps<{movement:MovementSummary;showDate?:boolean}>(),{showDate:false});</script>
<template><RouterLink :to="`/movements/${movement.id}`" class="movement-card card"><div :class="['time','mono',showDate&&'with-date']">{{showDate?showMonthDayTime(movement.movementTime):showTime(movement.movementTime)}}</div><div class="grow"><div :class="['direction-strip',movement.direction==='PRODUCTION_TO_WAREHOUSE'&&'return']">{{directionLabel(movement.direction)}}</div><div class="products">{{movement.productNames.join('、')}}<span v-if="movement.itemCount>movement.productNames.length"> 等 {{movement.itemCount}} 项</span></div><div class="meta">{{movement.totalCartons}} 个完整箱 · {{movement.totalQuantity}} 个 · {{movement.senderName}} → {{movement.receiverName}}</div><div class="badges"><span v-if="movement.status==='VOID'" class="status neutral">已作废</span><span v-else-if="movement.photoCount===0" class="status danger">缺少照片</span><span v-else class="status ok">{{movement.photoCount}} 张照片</span><span v-if="movement.hasIssues" class="status warn">有异常</span></div></div><span class="chevron">›</span></RouterLink></template>
